import type { NetworkWeights } from "@/types/nn";

// 700 (currPad / prevPad / currBall / prevBall / blocks / currObs / prevObs, 10 * 10 grids each) -> 48 -> 7 -> 6 -> 3 (moveL, moveR, stay)
//
// Hand-designed (closed form; no training, no play-testing). Every unit is sigmoid. Each grid is 1 on occupied cells.
// Idea: touching the obstacle on row 5 is game over, and the paddle edge decides where the ball goes after a hit
// (edgeL -> vx = -1, edgeR -> vx = +1). So while the ball falls, the agent predicts where it lands (with wall
// reflections) and catches it on the edge that sends it AWAY from the obstacle when it crosses row 5 again.
// While the ball rises (or did not move) it waits at the center.
// The prevPad / blocks / prevObs grids are not used (weight 0).
//
// Linear functions of the one-hot grids (valid while falling; prevBall is on the row above):
//   vy = Σ row * currBall - Σ row * prevBall                               (+1 falling, -1 rising, 0 when the ball did not move)
//   P  = Σ col * currPad = 3c                                              (paddle center c: 1 .. 8)
//   o  = Σ col * currObs                                                   (obstacle column)
//   u  = Σ x(10 - y) * currBall - Σ x(8 - y) * prevBall = x + vx (9 - y)   (column at the paddle row, walls ignored)
//   w  = Σ x( 9 - y) * currBall - Σ x(7 - y) * prevBall = x + vx (8 - y)   (column at row 8 = hit cell, walls ignored)
// Walls fold the unbounded column: fold(v) = -v (v < 0) | v (0 .. 9) | 18 - v (v > 9)
//   L  = fold(u)  landing column,   x8 = fold(w)  hit cell
//
// Choosing the edge: after a hit with direction d the ball crosses row 5 at fold(x8 + 3d), 3 ticks later.
// The obstacle does a random walk (±1 / tick), so the farther from o the safer. The farther side is
//   d = +1  <=>  o < m,   m = clamp(x8, 3, 6)   (midpoint of fold(x8 + 3) and fold(x8 - 3))
// and catching with that edge means the paddle center c* = L - d. Each tick: moveR <=> c* > c, moveL <=> c* < c.
// Both c* = L ± 1 cover L, so switching between them (the obstacle moves every tick) never loses the ball.
//   a = L - c:   moveR <=> a >= 1 + d,   moveL <=> a <= d - 1,   stay <=> a = d
//
// layer 1 (48; detectors on exact integers, |z| >= 10 at the nearest value)
//   F        = [vy = 1]                        z = 40 (vy - 0.5)
//   RR, RL   = [vy = -1 and c <= 3 / c >= 6]   z = ±8 (P - 10.5 / 16.5) - 200 (vy + 1)   (rising: go to the center)
//   U_j      = [u >= j]   j = -7 .. 17         z = 20 (u - j + 0.5)       ->  L  = 8 + Σ (fold(j) - fold(j - 1)) U_j
//   W_j      = [w >= j]   j = -5, -4, -3, 4, 5, 6, 13, 14, 15             ->  m  = 6 + Σ (m(j) - m(j - 1)) W_j
//   C_j      = [c >= j]   j = 2 .. 8           z = 8 (P - 3j + 1.5)       ->  c  = 1 + Σ C_j
//   O_j      = [o >= j]   j = 3 .. 6           z = 20 (o - j + 0.5)       ->  o' = 2 + Σ O_j = clamp(o, 2, 6)
//
// layer 2 (linear readout + threshold, gated by F: + 2000 (F - 1))
//   A2 = [a >= 2]   A0 = [a >= 0]   B0 = [a <= 0]   Bm2 = [a <= -2]   D = [m - o' >= 1] (d = +1)     z = 20 (... ± 0.5)
//   RR2, RL2 = sigmoid(20 RR - 10), sigmoid(20 RL - 10)   (pass through)
//
// layer 3 (AND)
//   r1 = [D and A2]   r2 = [not D and A0]   l1 = [D and B0]   l2 = [not D and Bm2]   RR3, RL3 (pass through)
//
// layer 4 (OR, decide)
//   moveL = sigmoid(10 (l1 + l2 + RL3))
//   moveR = sigmoid(10 (r1 + r2 + RR3))
//   stay  = sigmoid(5)                 (constant threshold; wins while all are ~0)
//
// Not predicted: the obstacle while the ball falls (it can not be steered), hits on blocks (re-read every tick).
// prettier-ignore
